import { test, expect } from '@playwright/test';

test.describe('Filter list by multiple statuses', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should filter the list by selected statuses', async ({ page }) => {
    await page.getByLabel('Status').check('Active');
    await page.getByLabel('Status').check('Pending');
    await page.getByRole('button', { name: 'Apply Filters' }).click();

    const filteredItems = await page.getByRole('listitem').all();
    expect(filteredItems.length).toBeGreaterThan(0);

    for (const item of filteredItems) {
      const status = await item.getByRole('status').innerText();
      expect(['Active', 'Pending']).toContain(status);
    }
  });

  test('should clear filters and show all items', async ({ page }) => {
    await page.getByLabel('Status').check('Active');
    await page.getByLabel('Status').check('Pending');
    await page.getByRole('button', { name: 'Apply Filters' }).click();

    await page.getByRole('button', { name: 'Clear Filters' }).click();

    const allItems = await page.getByRole('listitem').all();
    expect(allItems.length).toBeGreaterThan(0);
  });
});
